command:
if (!game.user.isGM) return ui.notifications.warn('Synchronize World Content is GM-only.');
if (game.combats.some(combat => combat.started && combat.scene)) {
  return ui.notifications.warn('Synchronize World Content can\'t run during an encounter.');
}

const proceed = await foundry.applications.api.DialogV2.confirm({
  window: { title: 'Synchronize World Content' },
  classes: ['emblem-rpg', 'dialog-editor'],
  content: '<div class="ed-container"><div class="ed-section">'
    + '<p class="ed-description" style="font-size:13px; font-style:normal;">'
    + 'Overwrites every actor and item imported from the content module, and every token placed from one, '
    + 'with its current version. Items a unit already carries keep whether they are equipped, their remaining '
    + 'uses and their refinement.</p></div></div>',
  rejectClose: false
});
if (!proceed) return;

const CONTENT = 'Compendium.emblem-rpg-content.';
const STUDIO = 'emblem-rpg-studio';
const HUD = 'flags.bg3-hud-core';
const REVISION = 'flags.emblem-rpg.hotbarLayoutRevision';
const COMPOSITIONS = 'flags.' + STUDIO + '.tokenComp';
const LEGACY_FLAGS = ['emblem-rpg.animV2', 'emblem-rpg.autoRally', 'emblem-rpg.selectedPassives',
  'emblem-rpg-content.recoveredFrom', 'core.sourceId', STUDIO + '.pixelArt', STUDIO + '.compositionKeyVersion']
  .map(path => 'flags.' + path);
const UNTOUCHED = [...LEGACY_FLAGS, REVISION];
const IDENTITY = ['_id', 'type', 'folder', 'sort', 'ownership', '_stats', 'items', 'effects'];
const { ForcedDeletion, ForcedReplacement } = foundry.data.operators;
const REFINED = /\s*\(\+\d+\)\s*$/;
/** What each carried copy keeps as its own: equipped state, remaining uses, forging progress and vendor stock. */
const COPY_STATE = ['system.isWielded', 'system.isWorn', 'system.isEquipped', 'system.uses.current',
  'system.craftingData.forgingXP', 'flags.emblem-rpg.stock', 'flags.emblem-rpg.vendorLocked'];
const summary = { actors: 0, tokens: 0, items: 0, renamed: [], skipped: [], errors: [] };

const canon = new Map();
for (const pack of game.packs) {
  if (pack.metadata.packageName !== 'emblem-rpg-content') continue;
  for (const document of await pack.getDocuments()) canon.set(document.uuid, document);
}

/** Whether a document was imported from the content module. A duplicate of an import is not one. */
function imported(document) {
  const stats = document?._source?._stats ?? {};
  return Boolean(stats.compendiumSource?.startsWith(CONTENT) && !stats.duplicateSource);
}

/** The content-module document an import came from, or null when it's gone or no longer the same type. */
async function lookup(document) {
  const uuid = document._source._stats.compendiumSource;
  if (!canon.has(uuid)) canon.set(uuid, await fromUuid(uuid).catch(() => null));
  const source = canon.get(uuid);
  return source?.documentName === document.documentName && source.type === document.type ? source : null;
}

/** The canon version to sync an import to. A missing source is reported, and a renamed import is left alone. */
async function canonOf(document, label) {
  const source = await lookup(document);
  if (!source) summary.skipped.push(label + ' / ' + document.name + ': ' + document._source._stats.compendiumSource);
  return source && !renamed(document, source, label) ? source : null;
}

/** Whether a document's name no longer matches its canon version's, and so is the GM's own. "(+N)" isn't a rename. */
function renamed(document, source, label) {
  const base = name => String(name ?? '').replace(REFINED, '').trim();
  if (base(document.name) === base(source.name)) return false;
  summary.renamed.push(label + ' / ' + document.name + ' <- ' + source.name);
  return true;
}

/** A Studio composition key in the ID format. Name- and index-keyed ones are legacy. */
function currentCompositionKey(key) {
  const parts = key.split('__');
  return parts.length === 3 && (parts[1] === 'none' || parts[1].startsWith('id-'));
}

/** Legacy nodes Migrate World Content owns, and the hotbar layout revision, which only ever advances. */
function untouched(path) {
  if (UNTOUCHED.includes(path)) return true;
  return path.startsWith(COMPOSITIONS + '.') && !currentCompositionKey(path.slice(COMPOSITIONS.length + 1));
}

/** Whether an untouched node sits somewhere under a path, so the path can't be deleted whole. */
function holdsUntouched(path) {
  return path === COMPOSITIONS || [...UNTOUCHED, COMPOSITIONS].some(root => root.startsWith(path + '.'));
}

/**
 * Flattened update data that makes `current` equal `target`. A key only `current` has is deleted, except for untouched
 * nodes. Nothing the schema dropped on load is ever seen here, so stored off-schema data stays where it is.
 */
function planPatch(current, target, prefix = '', changes = {}) {
  const plain = value => foundry.utils.getType(value) === 'Object';
  for (const key of new Set([...Object.keys(current ?? {}), ...Object.keys(target ?? {})])) {
    const path = prefix + key;
    if (untouched(path)) continue;
    const from = current?.[key];
    const to = target?.[key];
    if (!(key in (target ?? {}))) {
      if (from == null) continue;
      if (plain(from) && holdsUntouched(path)) planPatch(from, {}, path + '.', changes);
      else changes[path] = new ForcedDeletion();
    }
    else if (plain(from) && plain(to)) planPatch(from, to, path + '.', changes);
    else if (!(from == null && to == null) && !foundry.utils.equals(from, to)) {
      changes[path] = foundry.utils.deepClone(to);
    }
  }
  return changes;
}

/**
 * A copy of canon data in which every reference to one of the canon actor's own documents points at the unit's copy
 * instead, since an import keeps embedded IDs. BG3 HUD's hotbar and effect origins name items this way.
 */
function rebase(value, prefixes, to) {
  if (typeof value === 'string') {
    const from = prefixes.find(prefix => value.startsWith(prefix + '.'));
    return from ? to + value.slice(from.length) : value;
  }
  if (Array.isArray(value)) return value.map(entry => rebase(entry, prefixes, to));
  if (foundry.utils.getType(value) !== 'Object') return value;
  return Object.fromEntries(Object.entries(value).map(([key, entry]) => [key, rebase(entry, prefixes, to)]));
}

/** Put a carried copy's own state, and its "(+N)" suffix, into the canon data it's about to be matched to. */
function keepCopyState(document, target) {
  for (const path of COPY_STATE) {
    const value = foundry.utils.getProperty(document._source, path);
    if (value !== undefined) foundry.utils.setProperty(target, path, foundry.utils.deepClone(value));
    else {
      const parent = foundry.utils.getProperty(target, path.split('.').slice(0, -1).join('.'));
      if (foundry.utils.getType(parent) === 'Object') delete parent[path.split('.').at(-1)];
    }
  }
  const suffix = String(document.name ?? '').match(REFINED)?.[0].trim();
  if (suffix) target.name = String(target.name ?? '').replace(REFINED, '').trim() + ' ' + suffix;
  return target;
}

/**
 * The changes that make a document's own data match its canon version, leaving its identity and children alone. A
 * carried copy (`copy`) also keeps its own state. A changed hotbar is written whole, so a BG3 HUD save landing first
 * can't leave cells behind, and its revision advances so every client reloads it.
 */
function documentPatch(document, source, { kept = IDENTITY, relink = data => data, copy = false } = {}) {
  const strip = data => {
    for (const key of kept) delete data[key];
    return data;
  };
  const canonData = relink(strip(source.toObject()));
  const target = copy ? keepCopyState(document, canonData) : canonData;
  const changes = planPatch(strip(document.toObject()), target);
  if (document.documentName !== 'Actor') return changes;
  const hotbar = target.flags?.['bg3-hud-core']?.hudState;
  const cells = Object.keys(changes).filter(path => path.startsWith(HUD + '.hudState.'));
  if (hotbar !== undefined && cells.length) {
    for (const path of cells) delete changes[path];
    changes[HUD + '.hudState'] = ForcedReplacement.create(foundry.utils.deepClone(hotbar));
  }
  if (Object.keys(changes).some(path => path === HUD || path.startsWith(HUD + '.'))) {
    changes[REVISION] = (Number(foundry.utils.getProperty(document._source, REVISION)) || 0) + 1;
  }
  return changes;
}

/** An item the system grants and rebuilds by itself. */
const innate = item => Boolean(item.flags?.['emblem-rpg']?.innateGrant);

/** The Wielding, Wearing and Mounted markers the system keeps in step with what a unit has equipped. */
function marker(effect) {
  const flags = effect.flags?.['emblem-rpg'] ?? {};
  return flags.isWieldEffect === true || flags.isArmorEffect === true || flags.isMountEffect === true
    || effect.statuses?.has('Mounted') || String(effect.name ?? '').startsWith('Mounted: ');
}

async function inBatches(list, write) {
  for (let start = 0; start < list.length; start += 100) await write(list.slice(start, start + 100));
}

/**
 * Make one embedded collection match canon's, entry by ID, and bring each item's own effects in line. Entries the
 * system manages are never created, changed or deleted here. A missing item is created the way an import creates it,
 * without the arrival hooks that would unequip it, refill it or grant class features, and its equipped state then
 * follows as an ordinary update so the system's equipment markers catch up. Returns how many entries were written.
 */
async function syncCollection(parent, source, name, managed, options = {}) {
  const { relink = data => data, spared = async () => false } = options;
  const collection = parent.getEmbeddedCollection(name);
  const wanted = new Map(source.getEmbeddedCollection(name).filter(document => !managed(document))
    .map(document => [document.id, document]));
  const own = [];
  for (const document of collection) {
    const model = wanted.get(document.id)?.type === document.type ? wanted.get(document.id) : null;
    if (!managed(document) && !await spared(document, model)) own.push(document);
  }
  const kept = own.filter(document => wanted.get(document.id)?.type === document.type);
  const keptIds = new Set(kept.map(document => document.id));
  const deletes = own.filter(document => !keptIds.has(document.id)).map(document => document.id);
  const missing = [...wanted.keys()]
    .filter(id => !keptIds.has(id) && (deletes.includes(id) || !collection.has(id)));
  const creates = missing.map(id => {
    const data = relink(wanted.get(id).toObject());
    if (name === 'Item' && data.system && 'isWielded' in data.system) {
      Object.assign(data.system, { isWielded: false, isWorn: false, isEquipped: false });
    }
    return data;
  });
  await inBatches(deletes, ids => parent.deleteEmbeddedDocuments(name, ids, { render: false }));
  await inBatches(creates, data => parent.createEmbeddedDocuments(name, data,
    { keepId: true, render: false, noHook: name === 'Item' }));
  const updates = [...keptIds, ...missing].map(id => collection.get(id)).filter(Boolean)
    .map(document => ({ _id: document.id, ...documentPatch(document, wanted.get(document.id),
      { relink, copy: name === 'Item' && keptIds.has(document.id) }) }))
    .filter(update => Object.keys(update).length > 1);
  await inBatches(updates, data => parent.updateEmbeddedDocuments(name, data, { diff: false, render: false }));
  let written = new Set([...deletes, ...missing, ...updates.map(update => update._id)]).size;
  if (name === 'Item') {
    for (const document of kept) {
      const item = collection.get(document.id);
      const model = wanted.get(document.id);
      if (!item.effects.size && !model.effects.size) continue;
      written += await syncCollection(item, model, 'ActiveEffect', () => false, { relink });
    }
  }
  return written;
}

/**
 * Make an imported actor, or a placed token's own actor, match its canon version. An item on it that was renamed
 * from its own source is the GM's and stays. Returns whether the actor changed.
 */
async function syncActor(unit, source, { synthetic = false, label = unit.name } = {}) {
  const relink = data => rebase(data, [source.uuid, 'Actor.' + source.id], unit.uuid);
  const spared = async (item, model) => {
    const origin = model ?? (imported(item) ? await lookup(item) : null);
    return Boolean(origin) && renamed(item, origin, label);
  };
  const items = await syncCollection(unit, source, 'Item', innate, { relink, spared });
  const effects = await syncCollection(unit, source, 'ActiveEffect', marker, { relink });
  summary.items += items;
  const kept = synthetic ? [...IDENTITY, 'prototypeToken'] : IDENTITY;
  const changes = documentPatch(unit, source, { kept, relink });
  if (Object.keys(changes).length) await unit.update(changes, { diff: false });
  return Boolean(items || effects || Object.keys(changes).length);
}

/** Make each imported item in a list match its canon version, whether it sits in the world or on an actor. */
async function syncItems(items, label, parent = null) {
  const pairs = [];
  for (const item of items) {
    if (!imported(item)) continue;
    const source = await canonOf(item, label);
    if (source) pairs.push([item, source]);
  }
  const updates = pairs
    .map(([item, source]) => ({ _id: item.id, ...documentPatch(item, source, { copy: Boolean(parent) }) }))
    .filter(update => Object.keys(update).length > 1);
  await inBatches(updates, batch => parent
    ? parent.updateEmbeddedDocuments('Item', batch, { diff: false, render: false })
    : Item.updateDocuments(batch, { diff: false, render: false }));
  summary.items += updates.length;
  for (const [item, source] of pairs) {
    if (!item.effects.size && !source.effects.size) continue;
    summary.items += await syncCollection(item, source, 'ActiveEffect', () => false);
  }
}

for (const unit of game.actors) {
  if (unit._source._stats?.duplicateSource) continue;
  try {
    if (!imported(unit)) await syncItems(unit.items.contents, unit.name, unit);
    else {
      const source = await canonOf(unit, 'World actors');
      if (source && await syncActor(unit, source)) summary.actors += 1;
    }
  } catch (error) {
    summary.errors.push(unit.name + ': ' + error.message);
  }
}

try {
  await syncItems(game.items.contents, 'World items');
} catch (error) {
  summary.errors.push('World items: ' + error.message);
}

for (const scene of game.scenes) {
  for (const placed of scene.tokens) {
    const base = placed.baseActor;
    if (placed.actorLink || !placed.actor || !base || base._source._stats?.duplicateSource) continue;
    const label = scene.name + ' / ' + placed.name;
    try {
      if (!imported(base)) await syncItems(placed.actor.items.contents, label, placed.actor);
      else {
        const source = await lookup(base);
        if (!source || renamed(placed.actor, source, label)) continue;
        if (await syncActor(placed.actor, source, { synthetic: true, label })) summary.tokens += 1;
      }
    } catch (error) {
      summary.errors.push(label + ': ' + error.message);
    }
  }
}

console.group('emblem-rpg | Synchronize World Content');
console.log(summary);
console.groupEnd();
for (const entry of summary.skipped) console.warn('Synchronize World Content | No source, left as is: ' + entry);
for (const entry of summary.errors) console.error('Synchronize World Content | Failed: ' + entry);
if (summary.skipped.length) {
  ui.notifications.warn('Synchronize World Content: ' + summary.skipped.length + ' imported document(s) no longer '
    + 'have a source in the content module and were left as they are. See the console.');
}
if (summary.errors.length) {
  ui.notifications.error('Synchronize World Content: ' + summary.errors.length
    + ' document(s) failed. See the console.');
}
ui.notifications.info(summary.actors + ' actors, ' + summary.tokens + ' tokens and ' + summary.items
  + ' items synchronized.');
